"""Recalculate appendix multi-seed table values (seeds 42/123/456) with unified method."""
import json, sys
import numpy as np
from scipy.stats import spearmanr, rankdata
from collections import Counter
from pathlib import Path

sys.path.insert(0, '/root/autodl-tmp/struct_self_consist_ie/code')
from consistency import structural_consistency_soft_jaccard, fleiss_kappa_surface
from evaluation import per_instance_f1, compute_auroc  # Now fixed!

OUT_DIR = Path("/root/autodl-tmp/struct_self_consist_ie/output/d114_auroc_investigation")

def compute_mean_logprob(samples):
    logprobs = [s.get('mean_logprob') for s in samples if s.get('mean_logprob') is not None]
    logprobs = [lp for lp in logprobs if np.isfinite(lp)]
    return float(np.mean(logprobs)) if logprobs else float('nan')

def compute_em(samples, subtask='ner'):
    if subtask == 'ner':
        keys = [frozenset((e['text'], e['type']) for e in s.get('entities', [])) for s in samples]
    else:
        keys = [frozenset((r['head'], r['tail'], r['type']) for r in s.get('relations', [])) for s in samples]
    c = Counter(keys)
    N = len(samples)
    return c.most_common(1)[0][1] / N if keys else 0.0

def compute_vc(samples, subtask='ner'):
    N = len(samples)
    counter = Counter()
    if subtask == 'ner':
        for s in samples:
            for e in s.get('entities', []):
                counter[(e['text'], e['type'])] += 1
    else:
        for s in samples:
            for r in s.get('relations', []):
                counter[(r['head'], r['tail'], r['type'])] += 1
    rates = [v / N for v in counter.values()] if counter else [0.0]
    return float(np.mean(rates))

def analyze_auroc(data_path, subtask='ner'):
    with open(data_path) as f:
        data = [json.loads(line) for line in f if line.strip()]
    field = 'entities' if subtask == 'ner' else 'relations'
    instances = [d for d in data if len(d['gold'].get(field, [])) > 0]

    f1_vals = []
    sigs = {'SJ': [], 'FK': [], 'LP': [], 'EM': [], 'VC': []}
    for inst in instances:
        samples = inst['samples']
        gold = inst['gold']
        greedy = inst.get('greedy', samples[0])
        f1 = per_instance_f1(greedy, gold, subtask=subtask)
        f1_vals.append(f1)
        sigs['SJ'].append(structural_consistency_soft_jaccard(samples, subtask=subtask))
        sigs['FK'].append(fleiss_kappa_surface(samples, subtask=subtask))
        sigs['LP'].append(compute_mean_logprob(samples))
        sigs['EM'].append(compute_em(samples, subtask))
        sigs['VC'].append(compute_vc(samples, subtask))

    result = {}
    for sig in ['LP', 'FK', 'SJ', 'VC', 'EM']:
        v = np.array(sigs[sig])
        f1_arr = np.array(f1_vals)
        mask = np.isfinite(v) & np.isfinite(f1_arr)
        auroc = compute_auroc(v[mask].tolist(), f1_arr[mask].tolist())
        result[sig] = round(auroc, 4) if not np.isnan(auroc) else None
    return result

# Qwen SciERC NER (seeds 42, 123, 456)
qwen_paths = {
    42: '/root/autodl-tmp/struct_self_consist_ie/output/exp_012_rerun_1024/samples.jsonl',
    123: '/root/autodl-tmp/struct_self_consist_ie/output/exp_018_qwen_scierc_seed123/samples.jsonl',
    456: '/root/autodl-tmp/struct_self_consist_ie/output/exp_018_qwen_scierc_seed456/samples.jsonl',
}

# LLaMA SciERC NER (seeds 42, 123, 456)  
llama_paths = {
    456: '/root/autodl-tmp/struct_self_consist_ie/output/exp_018_llama_scierc_seed456_r1024/samples.jsonl',
}
# Need to find LLaMA seed 42 and 123 paths
import os
llama_42_candidates = [
    '/root/autodl-tmp/struct_self_consist_ie/output/exp_007_llama_seed42/samples.jsonl',
    '/root/autodl-tmp/struct_self_consist_ie/output/exp_007_llama/samples.jsonl',
]
for p in llama_42_candidates:
    if os.path.exists(p):
        llama_paths[42] = p
        break

print("=== Qwen SciERC NER AUROC (corrected, seeds 42/123/456) ===")
qwen_results = {}
for seed, path in sorted(qwen_paths.items()):
    if os.path.exists(path):
        r = analyze_auroc(path, 'ner')
        qwen_results[seed] = r
        print(f"  seed={seed}: LP={r['LP']}, FK={r['FK']}, SJ={r['SJ']}, VC={r['VC']}, EM={r['EM']}")

# Compute mean ± std
if len(qwen_results) == 3:
    print(f"\n  Mean ± std:")
    for sig in ['LP', 'FK', 'SJ', 'VC', 'EM']:
        vals = [qwen_results[s][sig] for s in [42, 123, 456] if qwen_results[s][sig] is not None]
        if vals:
            print(f"    {sig}: {np.mean(vals):.3f}±{np.std(vals):.3f}")

# Compare with appendix table
print("\n=== Comparison with current appendix table ===")
appendix_old = {'LP': '.613±.002', 'FK': '.618±.009', 'SJ': '.684±.009', 'VC': '.697±.010', 'EM': '.661±.010'}
print(f"  Old (paper): {appendix_old}")
if len(qwen_results) == 3:
    for sig in ['LP', 'FK', 'SJ', 'VC', 'EM']:
        vals = [qwen_results[s][sig] for s in [42, 123, 456]]
        print(f"  {sig}: new={np.mean(vals):.3f}±{np.std(vals):.3f}")

# Save appendix correction
appendix_correction = {
    'qwen_scierc_ner': {
        'seeds': [42, 123, 456],
        'per_seed': qwen_results,
        'mean_std': {}
    }
}
if len(qwen_results) == 3:
    for sig in ['LP', 'FK', 'SJ', 'VC', 'EM']:
        vals = [qwen_results[s][sig] for s in [42, 123, 456]]
        appendix_correction['qwen_scierc_ner']['mean_std'][sig] = {
            'mean': round(float(np.mean(vals)), 3),
            'std': round(float(np.std(vals)), 3),
        }

# Add to unified_auroc.json
unified_path = OUT_DIR / 'unified_auroc.json'
with open(unified_path) as f:
    unified = json.load(f)
unified['appendix_multiseed_corrected'] = appendix_correction
with open(unified_path, 'w') as f:
    json.dump(unified, f, indent=2)
print(f"\nUpdated {unified_path}")
